#include <iostream>
using namespace std;
template <typename T> size_t byValue(T x)      { return sizeof(x); }
template <typename T> size_t byRef(const T &x) { return sizeof(x); }
template <typename R, typename T> R as(T x)    { return static_cast<R>(x); }
int main() {
    double d[4] = {1.5, 2.5, 3.5, 4.5};
    cout << byValue(d) << " " << byRef(d) << endl;
    cout << as<int>(d[3]) << " " << as<char>(65) << " " << as<double>(7) / 2 << endl;
}

#include <iostream>
using namespace std;
template <typename T> void f(T)  { cout << "primary "; }
template <> void f<char>(char)   { cout << "spec-char "; }
void f(int)                      { cout << "ordinary "; }
int main() {
    f('x');
    f(7);
    f(7L);
    f<>(7);
    f<int>('x');
}

