What does this program print? Assume <iostream> and <string> are included and using namespace std; is in effect.

template <typename T>
T twice(T x) { return x + x; }
int main() {
    cout << twice(4) << " " << twice(1.5) << " " << twice(string("ab"));
    return 0;
}

What does this program print? Assume <iostream> is included and using namespace std; is in effect.

template <typename T>
void swapT(T &a, T &b) { T t = a; a = b; b = t; }
int main() {
    int x = 1, y = 2;
    char p = 'p', q = 'q';
    swapT(x, y);
    swapT(p, q);
    cout << x << y << p << q;
    return 0;
}

