Which numbered line causes a compile error?

template <class T>
class Box {
    T v;
public:
    Box(T x);
    T get() const;
    void set(T x);
};
template <class T> Box<T>::Box(T x) : v(x) {}         // line 1
template <class T> T Box<T>::get() { return v; }      // line 2
template <class T> void Box<T>::set(T x) { v = x; }   // line 3
int main() { Box<int> b(5); b.set(7); return 0; }     // line 4

What does this program print? Assume <iostream> is included and using namespace std; is in effect.

template <class T, int N>
class Ring {
    T d[N]; int pos = 0;
public:
    void put(T x);
    T get(int i) const { return d[i]; }
};
template <class T, int N>
void Ring<T, N>::put(T x) { d[pos] = x; pos = (pos + 1) % N; }
int main() {
    Ring<int, 3> r;
    for (int i = 1; i <= 5; i++) r.put(i * 10);
    cout << r.get(0) << " " << r.get(1) << " " << r.get(2);
    return 0;
}

